PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX saref: <https://w3id.org/saref#>

SELECT ?definition
WHERE {
  saref:Service rdfs:isDefinedBy ?definition .
}

PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ssn-system: <http://www.w3.org/ns/ssn/system/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?property
WHERE {
  {
    ?property rdfs:subClassOf* ssn:Property .
  }
  UNION
  {
    ?property rdf:type owl:Class ;
              rdfs:subClassOf* ssn:Property .
  }
  FILTER(?property != ssn:Property)
}

PREFIX : <http://example.org/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?device) AS ?numberOfDevices)
WHERE {
  ?device rdf:type :Device ;
          :softwareVersion "specificSoftwareVersion"^^xsd:string ;
          :serialNumber "specificSerialNumber"^^xsd:string .
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?range
WHERE {
  :readWrite rdfs:range ?range
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?range
WHERE {
  ?property rdf:type owl:DatatypeProperty ;
           rdfs:range ?range .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?isRepresentedBy ?represents
WHERE {
  ?isRepresentedBy rdf:type owl:ObjectProperty ;
                   owl:inverseOf ?represents .
}

PREFIX : <http://example.org/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT (COUNT(?thing) AS ?numberOfThings)
WHERE {
  ?composedThing a :ComposedThing ;
                 :isComposedBy ?thing .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?property ?domain ?range
WHERE {
  ?property rdfs:domain|owl:inverseOf owl:Thing .
  OPTIONAL { ?property rdfs:domain ?domain . }
  OPTIONAL { ?property rdfs:range ?range . }
}

