PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX s4bldg: <https://w3id.org/def/saref4bldg#>

SELECT ?property ?domain ?range
WHERE {
  ?property rdf:type owl:ObjectProperty ;
            rdfs:domain ?domain ;
            rdfs:range ?range .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4bldg: <https://w3id.org/def/saref4bldg#>
PREFIX geo: <http://www.opengis.net/ont/geosparql>

SELECT ?class ?role
WHERE {
  ?class rdf:type owl:Class .
  OPTIONAL { ?class rdfs:subClassOf ?superClass . }
  OPTIONAL { ?class rdfs:isDefinedBy ?definedBy . }
  BIND(
    COALESCE(
      IF(BOUND(?superClass), CONCAT("Subclass of ", STR(?superClass)), ""),
      IF(BOUND(?definedBy), CONCAT("Defined by ", STR(?definedBy)), "")
    ) AS ?role
  )
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?definition
WHERE {
  rdf:value rdfs:isDefinedBy ?definition .
}

