SELECT ?publisher
WHERE {
  <http://iot.linkeddata.es/def/core#> dc:publisher ?publisher
}

SELECT DISTINCT ?role ?individual
WHERE {
  <http://iot.linkeddata.es/def/core#> (dcterms:creator|dcterms:contributor) ?individual .
  BIND(IF(?predicate IN (dcterms:creator), "creator", "contributor") AS ?role)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT (COUNT(?contributor) AS ?numberOfContributors)
WHERE {
  ?resource dcterms:contributor ?contributor .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX vs: <http://www.w3.org/2003/06/sw-vocab-status/ns#>

SELECT (COUNT(?resource) AS ?count)
WHERE {
  ?resource vs:term_status "stable" ;
            dc:creator ?specific_creator .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property
WHERE {
  ?property rdf:type owl:AnnotationProperty
}
